import React from 'react';

import { formatDate } from '@dynatrace-sdk/units';

import { useCalendarContext } from '../../hooks/useCalendarContext.js';

/**
 * SelectMonthLabel component
 * Renders the formatted label for the select month view
 */
export const SelectMonthLabel = () => {
  const { state } = useCalendarContext();

  return <>{formatDate(state.activeDate, { year: 'numeric' })}</>;
};
SelectMonthLabel['displayName'] = 'SelectMonthLabel';
